package io.rift.cronos;
import android.app.*;import android.os.Bundle;import android.content.*;import android.graphics.Color;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Native custody UI, never hosted web content. Experimental receive/backup foundation; no signer. */
public final class WalletActivity extends Activity {
 private WalletVault vault;private LinearLayout body;private TextView output;private AlertDialog secretDialog;private EditText secretInput;private int action;private long generation;private boolean busy;private final ExecutorService io=Executors.newSingleThreadExecutor();private static final int AUTH=93;private interface Job{String run()throws Exception;}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);if(android.os.Build.VERSION.SDK_INT>=31)getWindow().setHideOverlayWindows(true);vault=new WalletVault(this);render();}
 private void label(String value){TextView text=new TextView(this);text.setText(value);text.setTextColor(Color.WHITE);text.setPadding(16,16,16,16);body.addView(text);}
 private void button(String value,Runnable fn){Button b=new Button(this);b.setText(value);b.setFilterTouchesWhenObscured(true);b.setOnClickListener(v->{if(!busy)fn.run();});body.addView(b);}
 private void render(){body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(20,36,20,24);body.setBackgroundColor(Color.rgb(9,11,18));ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);label("RIFT · MY CRONOS WALLET\nEXPERIMENTAL CUSTODY — DO NOT FUND WITH REAL ASSETS\nNative generation/recovery/backup foundation. Sending, mint signing and marketplace signing with this vault are NOT enabled. A generated address is not a full trading wallet yet. No cloud/seed reset or seed custody service.");try{String address=vault.address();if(address.isEmpty()){label("No local wallet. Device PIN/password required. New wallets use 24 English BIP39 words, no additional passphrase, account "+WalletCrypto.PATH+". This EVM address is not exclusive to Cronos; this app restricts network tools to chain 25.");button("Generate new wallet (device authentication)",()->authenticate(1));button("Recover TEST 12/24-word wallet (device authentication)",()->authenticate(2));}else{label("Public receiving address\n"+address+"\nBackup challenge completed: "+vault.backedUp()+"\nIf this app is uninstalled, data is cleared, or the device key is lost/invalidated, only your recovery phrase restores access. Keep it offline; never send it to support or websites.");button("Copy public receiving address",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Cronos address",address));});button("Reveal recovery phrase (device authentication)",()->authenticate(3));button("Check recovery backup (device authentication)",()->authenticate(4));button("Refresh this address's CRO balance",()->job(()->{org.json.JSONObject c=new SecureConnections(this).load();if(c.optString("mode").equals("offline"))throw new IllegalStateException();try(RequestControl control=new RequestControl(20000)){ReadOnlyRpc rpc=new ReadOnlyRpc(c.getString("rpc"),c.optString("key"),control);org.json.JSONObject r=rpc.balance(address,"");if(!c.getString("_readRevision").equals(new SecureConnections(this).load().getString("_readRevision")))throw new IllegalStateException();return r.toString(2);}}));button("Open native NFT tools for this address",()->startActivity(new Intent(this,HybridActivity.class).putExtra("publicOwner",address)));button("Delete local wallet (device authentication)",()->authenticate(5));}}catch(Exception e){label("Wallet record unavailable. Do not reset silently. Preserve your offline recovery phrase; device key recovery may be impossible. This build provides no cloud recovery.");}button("Refresh local wallet status",this::render);button("Back",this::finish);output=new TextView(this);output.setTextColor(Color.WHITE);output.setPadding(16,16,16,16);body.addView(output);}
 private void authenticate(int next){KeyguardManager manager=(KeyguardManager)getSystemService(KEYGUARD_SERVICE);if(manager==null||!manager.isDeviceSecure()){output.setText("Set a device PIN/password first; wallet operations fail closed without device security.");return;}Intent intent=manager.createConfirmDeviceCredentialIntent("RIFT native wallet","Confirm on your device. Recovery phrases never go to a website.");if(intent==null){output.setText("Device authentication unavailable.");return;}action=next;startActivityForResult(intent,AUTH);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=AUTH)return;int next=action;action=0;if(result!=RESULT_OK){output.setText("Authentication cancelled. No wallet action requested.");return;}if(next==1)new AlertDialog.Builder(this).setTitle("Generate experimental wallet?").setMessage("This build is not reviewed for real funds. Write the phrase offline. No clipboard/file/cloud seed export. Do not fund this address before device acceptance and security review.").setPositiveButton("Generate",(d,w)->job(()->{byte[] entropy=WalletCrypto.entropy();try{String a=vault.create(entropy);return "Wallet created: "+a+". Reveal phrase and complete backup check before relying on recovery. No transaction signing enabled.";}finally{Arrays.fill(entropy,(byte)0);}})).setNegativeButton("Cancel",null).show();else if(next==2)importPhrase();else if(next==3)reveal();else if(next==4)challenge();else if(next==5)delete();}
 private void protectDialog(AlertDialog dialog){if(dialog.getWindow()!=null){dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);dialog.getWindow().getDecorView().setFilterTouchesWhenObscured(true);if(android.os.Build.VERSION.SDK_INT>=31)dialog.getWindow().setHideOverlayWindows(true);}}
 @Override public boolean dispatchTouchEvent(MotionEvent event){if((event.getFlags()&(MotionEvent.FLAG_WINDOW_IS_OBSCURED|MotionEvent.FLAG_WINDOW_IS_PARTIALLY_OBSCURED))!=0)return false;return super.dispatchTouchEvent(event);}
 private EditText secretField(String hint){EditText input=new EditText(this);input.setHint(hint);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);input.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);input.setSaveEnabled(false);input.setFilterTouchesWhenObscured(true);secretInput=input;return input;}
 private void importPhrase(){EditText field=secretField("English BIP39 words, single spaces");secretDialog=new AlertDialog.Builder(this).setTitle("Recover wallet locally — experimental").setMessage("TEST PHRASES ONLY. Never import a phrase controlling real assets into this unreviewed debug build. No extra BIP39 passphrase supported. Submit within the five-minute device-auth window or retry authentication. Derivation "+WalletCrypto.PATH+". Your keyboard can see typed text; use a trusted offline keyboard. The phrase is processed only in native memory, not sent to RPC/web/backend.").setView(field).setPositiveButton("Recover",(d,w)->{final String words=field.getText().toString();field.setText("");secretInput=null;secretDialog=null;job(()->{byte[] entropy=WalletCrypto.parse(words);try{return "Recovered public address: "+vault.create(entropy)+". Reopen wallet screen to refresh; backup confirmation remains separate.";}finally{Arrays.fill(entropy,(byte)0);}});}).setNegativeButton("Cancel",null).create();secretDialog.setOnDismissListener(d->{field.setText("");if(secretInput==field)secretInput=null;});secretDialog.show();protectDialog(secretDialog);}
 private void reveal(){final long g=generation;busy=true;io.execute(()->{byte[] entropy=null;String phrase=null;try{entropy=vault.unlock();phrase=WalletCrypto.phrase(entropy);}catch(Exception ignored){}finally{if(entropy!=null)Arrays.fill(entropy,(byte)0);}final String words=phrase;runOnUiThread(()->{busy=false;if(g!=generation||isFinishing()||isDestroyed())return;if(words==null){output.setText("Unlock failed or authentication expired. Re-authenticate; no automatic reset.");return;}TextView text=new TextView(this);text.setText(words);text.setTextSize(19);text.setPadding(24,24,24,24);text.setTextIsSelectable(false);text.setSaveEnabled(false);secretDialog=new AlertDialog.Builder(this).setTitle("Write offline. Never share these words.").setMessage("Screen capture blocked where supported; cameras/root/compromised OS remain threats. No screenshots, clipboard or file export.").setView(text).setPositiveButton("Hide",(d,w)->text.setText("")).create();secretDialog.setOnDismissListener(d->text.setText(""));secretDialog.show();protectDialog(secretDialog);});});}
 private void challenge(){EditText field=secretField("Words 1, 6, 12 — separated by one space");secretDialog=new AlertDialog.Builder(this).setTitle("Check your written backup").setMessage("Enter words 1, 6 and 12 from your offline backup (both 12/24-word wallets). This is a local confirmation, not proof that your backup is safe.").setView(field).setPositiveButton("Check",(d,w)->{final String answer=field.getText().toString();field.setText("");secretInput=null;secretDialog=null;job(()->{byte[] entropy=vault.unlock();try{String[] words=WalletCrypto.phrase(entropy).split(" ");if(!(words[0]+" "+words[5]+" "+words[11]).equals(answer))throw new IllegalArgumentException();vault.confirmBackup();return "Backup challenge confirmed locally. Reopen screen to refresh. Keep all words offline; no cloud recovery exists.";}finally{Arrays.fill(entropy,(byte)0);}});}).setNegativeButton("Cancel",null).create();secretDialog.setOnDismissListener(d->{field.setText("");if(secretInput==field)secretInput=null;});secretDialog.show();protectDialog(secretDialog);}
 private void delete(){try{final String address=vault.address();EditText field=secretField("Type DELETE "+address.substring(address.length()-6));secretDialog=new AlertDialog.Builder(this).setTitle("Delete this device's wallet?").setMessage("Funds are NOT moved. Connection reset does NOT delete your wallet. Without your recovery words, deletion/uninstall can permanently lose access. This is not guaranteed physical secure erase.").setView(field).setPositiveButton("Delete locally",(d,w)->{String confirm=field.getText().toString();field.setText("");secretInput=null;secretDialog=null;if(!confirm.equals("DELETE "+address.substring(address.length()-6))){output.setText("Deletion confirmation did not match.");return;}job(()->{vault.delete(address);return "Local wallet removed. No on-chain assets moved. Reopen wallet screen to refresh.";});}).setNegativeButton("Cancel",null).create();secretDialog.setOnDismissListener(d->{field.setText("");if(secretInput==field)secretInput=null;});secretDialog.show();protectDialog(secretDialog);}catch(Exception e){output.setText("Unable to inspect wallet for deletion; no reset performed.");}}
 private void job(Job task){if(busy)return;busy=true;long g=generation;output.setText("Working locally… no signing or spending.");io.execute(()->{String message;try{message=task.run();}catch(Exception e){message="Wallet operation failed, authentication expired, or settings unavailable. No automatic reset. Reopen/re-authenticate before retrying. Secret/provider details are intentionally hidden.";}final String value=message;runOnUiThread(()->{busy=false;if(g==generation&&!isFinishing()&&!isDestroyed()){render();output.setText(value);}});});}
 @Override protected void onPause(){generation++;if(secretInput!=null){secretInput.setText("");secretInput=null;}if(secretDialog!=null){secretDialog.dismiss();secretDialog=null;}super.onPause();}
 @Override protected void onDestroy(){generation++;io.shutdownNow();super.onDestroy();}
}
